import { readFileSync } from 'node:fs';
import express from 'express';
import swaggerUi from 'swagger-ui-express';
import router from './src/router.js';

// Generated by `npm run swagger`.
const swaggerDocument = JSON.parse(
  readFileSync(new URL('./swagger.json', import.meta.url), 'utf8'),
);

const app = express();

app.use(express.json());

app.get('/', (req, res) => {
  res.send('Books Web Service is running');
});

app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));

app.use(router);

// express.json() passes malformed request bodies here instead of to a route.
// Express only treats a middleware as an error handler if it takes four arguments.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({ message: 'Request body must be valid JSON' });
  }
  console.error('Unhandled error:', err.message);
  return res.status(500).json({ message: 'Internal server error' });
});

export default app;
